-- mod-tome/data/talents/gifts/storm-drake.lua
-- Total: 12 cadenas
-- Estado: ⏳ Pendiente
-- Ultima actualizacion: --
-- Traductor: --

t("Lightning Speed", "Relámpago Speed", "talent name")
t("Static Field", "Estatico Campo", "talent name")
t("%s resists the static field!", "%s resiste el campo estático!", "logSeen")
t("%s is caught in the static field!", "%s es atrapado en el campo estático!", "logSeen")
t("#PURPLE#%d STATIC#LAST#", "#PURPLE##%d                                                                                      ", "tformat")
t("Tornado", "o Tornado", "talent name")
t("Tornado", "Tornado", "_t")
t("%s is knocked back!", "%s   está devuelta!", "logSeen")
t("%s resists the knockback!", "%s resiste el golpe!", "logSeen")
t("Lightning Breath", "Aliento de relámpago", "talent name")
t("@Source@ breathes lightning!", "@Source@ respira rayos!", "_t")
t("%s resists the stun!", "%s resiste el truco!", "logSeen")

t("You transform into pure lightning, moving %d%% faster for %d game turns.\n\t\tAlso provides 30%% physical damage resistance and 100%% lightning resistance.\n\t\tAny actions other than moving will stop this effect.\n\t\tNote: since you will be moving very fast, game turns will pass very slowly.\n\t\tLevels in Lightning Speed additionally raises your Movement Speed by %d%%, passively.\n\t\tEach point in storm drake talents also increases your lightning resistance by 1%%.", "Te transformas en un rayo puro, moviendo %d %% más rápido para los giros del juego %d.\nTambién proporciona resistencia al daño físico 30%% y resistencia al rayo 100%%.\nCualquier acción que no se mueva parará este efecto.\nNota: ya que se mueve muy rápido, los turnos de juego pasarán muy lentamente.\nLos niveles de velocidad de relámpago aumentan su velocidad de movimiento por %d %%, pasivamente.\nCada punto en los talentos de la tormenta también aumenta su resistencia al rayo por 1%%.", "tformat")
t("Generate an electrical field around you in a radius of %d. Any creature caught inside will lose up to %0.1f%% of its current life (%0.1f%% if the target is Elite or Rare, %0.1f%% if the target is a Unique or Boss, and %0.1f%% if they are an Elite Boss.). This life drain is irresistable, but can be saved against with physical save.\n\t\tAdditionally, it will deal %0.2f lightning damage afterwards, regardless of target rank.\n\t\tCurrent life loss and lightning damage will increase with your Mindpower, and the lightning damage element can critically hit with mental critical chances.\n\t\tEach point in storm drake talents also increases your lightning resistance by 1%%.", "Generar un campo eléctrico a tu alrededor en un radio de %d. Cualquier criatura atrapada dentro perderá hasta %0.1f %% de su vida actual (%0.1f %% si el objetivo es Elite o Rare, %0.1f %% si el objetivo es un Único o Jefe, y %0.1f %% si son un Jefe Elite.). Este drenaje de vida es irresistable, pero se puede salvar con ahorro físico.\nAdemás, tratará los daños causados por los rayos %0.2f después, independientemente del rango de destino.\nLa pérdida de vida actual y el daño de relámpago aumentarán con su poder mental, y el elemento de daño de relámpago puede golpear críticamente con posibilidades críticas mentales.\nCada punto en los talentos de la tormenta también aumenta su resistencia al rayo por 1%%.", "tformat")
t("Summon a tornado that moves very slowly towards the target, following it if it changes position.\n\t\tEach time it moves every foes within radius 2 takes %0.2f lightning damage and is knocked back 2 spaces.\n\t\tWhen it reaches the target it explodes in a radius of %d, knocking back targets and dealing %0.2f lightning and %0.2f physical damage.\n\t\tThe tornado will move a maximum of 20 times.\n\t\tDamage will increase with your Mindpower.\n\t\tEach point in storm drake talents also increases your lightning resistance by 1%%.", "Invoca un tornado que se mueve muy lentamente hacia el objetivo, siguiendolo si cambia de posición.\nCada vez que mueve a cada enemigo dentro del radio 2 toma daño de rayo %0.2f y se llama de nuevo 2 espacios.\nCuando alcanza el objetivo explote en un radio de %d, golpeando los objetivos y tratando el rayo de %0.2f y el daño físico %0.2f.\nEl tornado se moverá un máximo de 20 veces.\nEl daño aumentará con tu poder mental.\nCada punto en los talentos de la tormenta también aumenta su resistencia al rayo por 1%%.", "tformat")
t("You breathe lightning in a frontal cone of radius %d. Any target caught in the area will take %0.2f to %0.2f lightning damage (%0.2f average) and be stunned for 3 turns.\n\t\tThe damage will increase with your Strength, and the critical chance is based on your Mental crit rate, and the Stun apply power is based on your Mindpower.\n\t\tEach point in storm drake talents also increases your lightning resistance by 1%%.", "Respira rayos en un cono frontal de radio %d. Cualquier objetivo atrapado en la zona tomará %0.2f a %0.2f daños de relámpago (promedio de %0.2f) y será aturdido por 3 vueltas.\nEl daño aumentará con su fuerza, y la probabilidad crítica se basa en su tasa de criminalidad mental, y el poder de aplicación Stun se basa en su poder mental.\nCada punto en los talentos de la tormenta también aumenta su resistencia al rayo por 1%%.", "tformat")
